<?php
declare(strict_types=1);
namespace ChezVous\Features\Tasks;
use PDO;
final class TaskRepository { public function __construct(private PDO $db) {} public function all(): array { return $this->db->query('SELECT t.*, d.name department, u.name assignee, e.client_name event_client FROM tasks t LEFT JOIN departments d ON d.id=t.department_id LEFT JOIN users u ON u.id=t.assignee_id LEFT JOIN events e ON e.id=t.event_id ORDER BY FIELD(t.status,"A fazer","Em andamento","Em validação","Concluída","Bloqueada"), t.due_at')->fetchAll(); } public function create(array $d): int { $s=$this->db->prepare('INSERT INTO tasks(title,department_id,assignee_id,event_id,validator_name,priority,due_at,description) VALUES (:title,:department_id,:assignee_id,:event_id,:validator_name,:priority,:due_at,:description)');$s->execute($d);return (int)$this->db->lastInsertId(); } public function toggle(int $id): void { $s=$this->db->prepare("UPDATE tasks SET status=IF(status='Concluída','A fazer','Concluída'), completed_at=IF(status='Concluída',NULL,NOW()) WHERE id=:id");$s->execute(['id'=>$id]); } public function validate(int $id): void { $s=$this->db->prepare("UPDATE tasks SET status='Concluída', completed_at=NOW() WHERE id=:id AND status='Em validação'");$s->execute(['id'=>$id]); }}
